interface IBus
{
    Task PublishAsync(string key, CancellationToken ct);
    Task PublishAsync(string key) => PublishAsync(key, CancellationToken.None);
}

sealed class RabbitBus : IBus
{
    Task IBus.PublishAsync(string key, CancellationToken ct) => Task.CompletedTask;
}

IBus bus = new RabbitBus();
await bus.PublishAsync("grading.completed");
